// شعارات أندية رابطة تيبازة الـ 11 المعتمدة
const LOGOS = {"1": "data:image/png;base64,", "2": "data:image/png;base64,", "3": "data:image/png;base64,", "4": "data:image/png;base64,", "5": "data:image/png;base64,", "6": "data:image/png;base64,", "7": "data:image/png;base64,", "8": "data:image/png;base64,", "9": "data:image/png;base64,", "10": "data:image/png;base64,", "11": "data:image/png;base64,"};

function getTeamLogo(id){
  return (typeof LOGOS !== "undefined" && LOGOS[id]) ? LOGOS[id] : "";
}

function teamLogoImg(id, size){
  const s = size || 26;
  const src = getTeamLogo(id);
  if(!src) return "";
  return `<img src="${src}" class="team-logo-img" style="width:${s}px;height:${s}px;border-radius:50%;object-fit:cover;vertical-align:middle;border:1px solid rgba(0,0,0,0.08);background:#fff;flex-shrink:0;" alt="">`;
}
